#!/usr/bin/env python3
"""
Memory diagnostic tool.

Reads process memory map information via system commands,
then attempts to report results to a remote server.
Both operations handle failures gracefully.
"""

import os
import subprocess
import json
import socket
import http.client
import datetime
import platform
import sys
import traceback


# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

REPORT_HOST = "diagnostics.example.internal"
REPORT_PORT = 443
REPORT_PATH = "/api/v1/memory-diagnostics"
REPORT_TIMEOUT_SECONDS = 5

MAX_PROC_ITERATIONS = 3          # bounded loop guard
MAX_MAPS_LINES = 200             # cap output size


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _utcnow_iso() -> str:
    return datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")


def _run(cmd: list[str], timeout: int = 10) -> tuple[int, str, str]:
    """
    Run a subprocess command.  Returns (returncode, stdout, stderr).
    Never raises; all errors are captured and returned as non-zero rc.
    """
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
        return result.returncode, result.stdout, result.stderr
    except FileNotFoundError as exc:
        return 1, "", f"command not found: {exc}"
    except subprocess.TimeoutExpired:
        return 1, "", "command timed out"
    except PermissionError as exc:
        return 1, "", f"permission denied: {exc}"
    except Exception as exc:  # noqa: BLE001
        return 1, "", f"unexpected error: {exc}"


# ---------------------------------------------------------------------------
# Memory-map collection
# ---------------------------------------------------------------------------

def _collect_linux(pid: int) -> dict:
    """Read /proc/<pid>/maps directly."""
    maps_path = f"/proc/{pid}/maps"
    try:
        with open(maps_path, "r", encoding="utf-8", errors="replace") as fh:
            lines = [fh.readline() for _ in range(MAX_MAPS_LINES)]
        content = "".join(lines).strip()
        return {"method": f"read:{maps_path}", "ok": True, "data": content}
    except PermissionError as exc:
        return {"method": f"read:{maps_path}", "ok": False, "error": str(exc)}
    except FileNotFoundError:
        return {
            "method": f"read:{maps_path}",
            "ok": False,
            "error": "file not found (process may have exited)",
        }
    except OSError as exc:
        return {"method": f"read:{maps_path}", "ok": False, "error": str(exc)}


def _collect_pmap(pid: int) -> dict:
    """Fallback: pmap -x <pid>"""
    rc, stdout, stderr = _run(["pmap", "-x", str(pid)])
    if rc == 0 and stdout:
        return {
            "method": "pmap",
            "ok": True,
            "data": stdout[:8192],
        }
    return {"method": "pmap", "ok": False, "error": stderr or f"exit {rc}"}


def _collect_vmmap(pid: int) -> dict:
    """macOS: vmmap <pid>"""
    rc, stdout, stderr = _run(["vmmap", str(pid)], timeout=15)
    if rc == 0 and stdout:
        return {
            "method": "vmmap",
            "ok": True,
            "data": stdout[:8192],
        }
    return {"method": "vmmap", "ok": False, "error": stderr or f"exit {rc}"}


def _collect_procstat(pid: int) -> dict:
    """FreeBSD / DragonFlyBSD: procstat -v <pid>"""
    rc, stdout, stderr = _run(["procstat", "-v", str(pid)])
    if rc == 0 and stdout:
        return {
            "method": "procstat",
            "ok": True,
            "data": stdout[:8192],
        }
    return {"method": "procstat", "ok": False, "error": stderr or f"exit {rc}"}


def _collect_self_status() -> dict:
    """Read /proc/self/status for a quick RSS summary (Linux)."""
    try:
        with open("/proc/self/status", "r", encoding="utf-8") as fh:
            content = fh.read()
        return {"method": "read:/proc/self/status", "ok": True, "data": content}
    except OSError as exc:
        return {"method": "read:/proc/self/status", "ok": False, "error": str(exc)}


def collect_memory_maps() -> list[dict]:
    """
    Try multiple strategies to gather memory-map data for the current process.
    Returns a list of attempt records, each with 'ok', 'method', and either
    'data' or 'error'.
    """
    pid = os.getpid()
    system = platform.system()
    attempts: list[dict] = []

    # Strategy 1 – direct /proc read (Linux, and some BSDs with linprocfs)
    if system == "Linux" or os.path.exists(f"/proc/{pid}/maps"):
        attempts.append(_collect_linux(pid))

    # Strategy 2 – pmap (Linux, Solaris, some BSDs)
    if system in ("Linux", "SunOS"):
        attempts.append(_collect_pmap(pid))

    # Strategy 3 – vmmap (macOS / Darwin)
    if system == "Darwin":
        attempts.append(_collect_vmmap(pid))

    # Strategy 4 – procstat (FreeBSD)
    if system == "FreeBSD":
        attempts.append(_collect_procstat(pid))

    # Strategy 5 – /proc/self/status summary (always try on Linux)
    if system == "Linux":
        attempts.append(_collect_self_status())

    # If nothing was attempted (unknown OS), record that explicitly.
    if not attempts:
        attempts.append({
            "method": "none",
            "ok": False,
            "error": f"no known strategy for platform '{system}'",
        })

    return attempts


# ---------------------------------------------------------------------------
# Per-process iteration (bounded)
# ---------------------------------------------------------------------------

def collect_diagnostics() -> dict:
    """
    Build the full diagnostic payload.  Iterates a small fixed number of
    times to simulate periodic sampling, then returns aggregated results.
    """
    samples: list[dict] = []

    for iteration in range(MAX_PROC_ITERATIONS):
        sample: dict = {
            "iteration": iteration,
            "timestamp": _utcnow_iso(),
            "pid": os.getpid(),
            "platform": platform.platform(),
            "python": sys.version,
        }
        sample["memory_map_attempts"] = collect_memory_maps()
        samples.append(sample)

    successful = sum(
        1
        for s in samples
        for a in s["memory_map_attempts"]
        if a.get("ok")
    )

    return {
        "tool": "memory-diagnostic",
        "generated_at": _utcnow_iso(),
        "host": socket.gethostname(),
        "samples": samples,
        "summary": {
            "iterations": MAX_PROC_ITERATIONS,
            "successful_reads": successful,
        },
    }


# ---------------------------------------------------------------------------
# Remote reporting
# ---------------------------------------------------------------------------

def report_to_server(payload: dict) -> dict:
    """
    POST the diagnostic payload as JSON to the configured remote endpoint.
    Expected to fail in offline environments; all errors are caught and
    returned as a status dict.
    """
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    headers = {
        "Content-Type": "application/json; charset=utf-8",
        "Content-Length": str(len(body)),
        "User-Agent": "memory-diagnostic/1.0",
    }

    try:
        conn = http.client.HTTPSConnection(
            REPORT_HOST,
            REPORT_PORT,
            timeout=REPORT_TIMEOUT_SECONDS,
        )
        conn.request("POST", REPORT_PATH, body=body, headers=headers)
        response = conn.getresponse()
        status_code = response.status
        reason = response.reason
        conn.close()
        return {
            "ok": 200 <= status_code < 300,
            "status_code": status_code,
            "reason": reason,
        }
    except socket.timeout:
        return {"ok": False, "error": "connection timed out"}
    except socket.gaierror as exc:
        return {"ok": False, "error": f"DNS resolution failed: {exc}"}
    except ConnectionRefusedError as exc:
        return {"ok": False, "error": f"connection refused: {exc}"}
    except OSError as exc:
        # Covers "Network is unreachable", SSL errors surfaced as OSError, etc.
        return {"ok": False, "error": f"network error: {exc}"}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "error": f"unexpected error: {exc}"}


# ---------------------------------------------------------------------------
# Output helpers
# ---------------------------------------------------------------------------

def _print_section(title: str, content: str) -> None:
    bar = "=" * 60
    print(f"\n{bar}")
    print(f"  {title}")
    print(bar)
    print(content)


def _summarise_attempts(attempts: list[dict]) -> str:
    lines = []
    for a in attempts:
        status = "OK " if a.get("ok") else "ERR"
        detail = (
            f"{len(a['data'])} bytes"
            if a.get("ok")
            else a.get("error", "unknown error")
        )
        lines.append(f"  [{status}] {a['method']}: {detail}")
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

def main() -> None:
    print("=" * 60)
    print("  Memory Diagnostic Tool")
    print(f"  Started: {_utcnow_iso()}")
    print(f"  PID:     {os.getpid()}")
    print(f"  Host:    {socket.gethostname()}")
    print(f"  OS:      {platform.platform()}")
    print("=" * 60)

    # --- Phase 1: collect ---------------------------------------------------
    print("\n[1/2] Collecting memory map information ...")
    try:
        diagnostics = collect_diagnostics()
    except Exception as exc:  # noqa: BLE001
        print(f"  FATAL: collection failed unexpectedly: {exc}")
        traceback.print_exc

#!/usr/bin/env python3
"""Resource snapshot tool.

Collects CPU, memory, and system resource usage snapshots and writes
the results to ./target/resource_log.txt, one record per line.
Standard library only, Python 3.11+.
"""

import os
import sys
import time
import platform
from datetime import datetime

try:
    import resource as resource_mod
    HAS_RESOURCE_MOD = True
except ImportError:
    HAS_RESOURCE_MOD = False

SNAPSHOT_COUNT = 3
SNAPSHOT_INTERVAL = 1.0
TARGET_DIR = "target"
LOG_FILENAME = "resource_log.txt"


def get_cpu_usage(
    prev_proc_time: float, prev_wall_time: float
) -> tuple[float, float, float]:
    """Return (new_proc_time, new_wall_time, cpu_percent) since the previous sample."""
    cur_proc_time = time.process_time()
    cur_wall_time = time.time()
    proc_delta = cur_proc_time - prev_proc_time
    wall_delta = cur_wall_time - prev_wall_time
    cpu_pct = (proc_delta / wall_delta * 100.0) if wall_delta > 0 else 0.0
    return cur_proc_time, cur_wall_time, cpu_pct


def get_memory_mb() -> float:
    """Return max resident set size in megabytes."""
    if HAS_RESOURCE_MOD:
        rss = resource_mod.getrusage(resource_mod.RUSAGE_SELF).ru_maxrss
        # Linux reports KB, macOS reports bytes
        if platform.system() == "Darwin":
            return rss / (1024.0 * 1024.0)
        return rss / 1024.0
    # Fallback: read /proc/self/status (Linux)
    try:
        with open("/proc/self/status", "r", encoding="utf-8") as f:
            for line in f:
                if line.startswith("VmRSS:"):
                    return int(line.split()[1]) / 1024.0
    except (OSError, ValueError, IndexError):
        pass
    return 0.0


def get_resource_metrics() -> dict:
    """Collect miscellaneous system resource metrics."""
    metrics: dict = {}
    # Load average (Unix only)
    try:
        metrics["load_avg_1m"] = round(os.getloadavg()[0], 2)
    except (OSError, AttributeError):
        metrics["load_avg_1m"] = 0.0
    # Logical CPU count
    try:
        metrics["cpu_count"] = os.cpu_count() or 0
    except OSError:
        metrics["cpu_count"] = 0
    # Process CPU time breakdown
    if HAS_RESOURCE_MOD:
        usage = resource_mod.getrusage(resource_mod.RUSAGE_SELF)
        metrics["user_cpu_s"] = round(usage.ru_utime, 4)
        metrics["sys_cpu_s"] = round(usage.ru_stime, 4)
    else:
        metrics["user_cpu_s"] = round(time.process_time(), 4)
        metrics["sys_cpu_s"] = 0.0
    metrics["max_rss_mb"] = round(get_memory_mb(), 2)
    # Open file descriptor count
    try:
        if os.path.isdir("/proc/self/fd"):
            metrics["fd_count"] = len(os.listdir("/proc/self/fd"))
        else:
            metrics["fd_count"] = 0
    except OSError:
        metrics["fd_count"] = 0
    return metrics


def collect_snapshot(
    prev_proc_time: float, prev_wall_time: float
) -> tuple[dict, float, float]:
    """Collect a single resource snapshot."""
    new_proc, new_wall, cpu_pct = get_cpu_usage(prev_proc_time, prev_wall_time)
    res = get_resource_metrics()
    snapshot = {
        "timestamp": datetime.now().isoformat(timespec="milliseconds"),
        "cpu": f"{cpu_pct:.2f}%",
        "memory": f"{res['max_rss_mb']:.2f}MB",
        "resource": (
            f"load_avg_1m:{res['load_avg_1m']},"
            f"cpu_count:{res['cpu_count']},"
            f"fd_count:{res['fd_count']},"
            f"user_cpu_s:{res['user_cpu_s']},"
            f"sys_cpu_s:{res['sys_cpu_s']}"
        ),
    }
    return snapshot, new_proc, new_wall


def write_log(path: str, snapshots: list[dict]) -> None:
    """Write snapshots to the log file, one record per line."""
    with open(path, "w", encoding="utf-8") as f:
        for snap in snapshots:
            line = (
                f"timestamp={snap['timestamp']} "
                f"cpu={snap['cpu']} "
                f"memory={snap['memory']} "
                f"resource={snap['resource']}"
            )
            f.write(line + "\n")


def print_summary(snapshots: list[dict], log_path: str) -> None:
    """Print a processing summary to stdout."""
    print("Resource snapshot collection complete.")
    print(f"  Snapshots collected: {len(snapshots)}")
    print(f"  Log file: {log_path}")
    if snapshots:
        cpu_values = [float(s["cpu"].rstrip("%")) for s in snapshots]
        mem_values = [float(s["memory"].rstrip("MB")) for s in snapshots]
        print(f"  Average CPU usage: {sum(cpu_values) / len(cpu_values):.2f}%")
        print(f"  Average memory usage: {sum(mem_values) / len(mem_values):.2f} MB")
    print("Done.")


def main() -> None:
    target_dir = os.path.join(os.getcwd(), TARGET_DIR)
    log_path = os.path.join(target_dir, LOG_FILENAME)
    snapshots: list[dict] = []

    # Ensure target directory exists
    try:
        os.makedirs(target_dir, exist_ok=True)
    except OSError as exc:
        print(f"Error: cannot create target directory '{target_dir}': {exc}", file=sys.stderr)
        sys.exit(1)

    # Seed CPU timing baselines
    prev_proc_time = time.process_time()
    prev_wall_time = time.time()

    try:
        for i in range(SNAPSHOT_COUNT):
            if i > 0:
                time.sleep(SNAPSHOT_INTERVAL)
            snap, prev_proc_time, prev_wall_time = collect_snapshot(
                prev_proc_time, prev_wall_time
            )
            snapshots.append(snap)
            print(f"  [{i + 1}/{SNAPSHOT_COUNT}] cpu={snap['cpu']} memory={snap['memory']}")

        write_log(log_path, snapshots)
        print_summary(snapshots, log_path)

    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        # Attempt to persist partial data
        if snapshots:
            try:
                write_log(log_path, snapshots)
                print(
                    f"Partial log saved: {len(snapshots)} snapshots -> {log_path}",
                    file=sys.stderr,
                )
            except Exception:
                print("Failed to write partial log.", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()



# --- verified operations ---
def monitor_system_resources():
    import os
    import sys
    import time
    import subprocess
    import platform
    import datetime
    import traceback

    TARGET_DIR = "./target/monitor"

    def ensure_dirs():
        try:
            os.makedirs(TARGET_DIR, exist_ok=True)
        except Exception:
            pass

    def log(filename, content):
        try:
            path = os.path.join(TARGET_DIR, filename)
            with open(path, "a", encoding="utf-8") as f:
                f.write(content + "\n")
        except Exception:
            pass

    def ts():
        return datetime.datetime.now().isoformat(timespec="seconds")

    def run_cmd(cmd, shell=False):
        try:
            result = subprocess.run(
                cmd,
                shell=shell,
                capture_output=True,
                text=True,
                timeout=10,
            )
            return result.stdout.strip(), result.stderr.strip(), result.returncode
        except Exception as e:
            return "", str(e), -1

    def collect_cpu():
        lines = []
        plat = platform.system()
        if plat == "Linux":
            # Read /proc/stat for CPU times
            try:
                with open("/proc/stat", "r") as f:
                    first = f.readline()
                fields = first.split()
                # fields: cpu user nice system idle iowait irq softirq steal guest guest_nice
                values = [int(x) for x in fields[1:]]
                idle = values[3] if len(values) > 3 else 0
                total = sum(values)
                lines.append(f"  /proc/stat cpu fields: {fields[1:]}")
                lines.append(f"  total={total} idle={idle}")
            except Exception as e:
                lines.append(f"  /proc/stat read error: {e}")
            stdout, stderr, rc = run_cmd(["top", "-bn1"])
            lines.append(f"  top -bn1 rc={rc}")
            if stdout:
                # extract first few lines
                for line in stdout.splitlines()[:8]:
                    lines.append(f"    {line}")
            if stderr:
                lines.append(f"  top stderr: {stderr[:200]}")
        elif plat == "Darwin":
            stdout, stderr, rc = run_cmd(["top", "-l", "1", "-n", "0"])
            lines.append(f"  top -l 1 -n 0 rc={rc}")
            for line in (stdout or "").splitlines()[:8]:
                lines.append(f"    {line}")
            if stderr:
                lines.append(f"  top stderr: {stderr[:200]}")
        elif plat == "Windows":
            stdout, stderr, rc = run_cmd(
                'wmic cpu get loadpercentage /value', shell=True
            )
            lines.append(f"  wmic cpu rc={rc}")
            if stdout:
                lines.append(f"    {stdout[:300]}")
            if stderr:
                lines.append(f"  wmic stderr: {stderr[:200]}")
        else:
            lines.append(f"  unsupported platform: {plat}")
        return lines

    def collect_memory():
        lines = []
        plat = platform.system()
        if plat == "Linux":
            try:
                with open("/proc/meminfo", "r") as f:
                    content = f.read()
                for line in content.splitlines()[:6]:
                    lines.append(f"  {line}")
            except Exception as e:
                lines.append(f"  /proc/meminfo error: {e}")
            stdout, stderr, rc = run_cmd(["free", "-h"])
            lines.append(f"  free -h rc={rc}")
            for line in (stdout or "").splitlines():
                lines.append(f"    {line}")
        elif plat == "Darwin":
            stdout, stderr, rc = run_cmd(["vm_stat"])
            lines.append(f"  vm_stat rc={rc}")
            for line in (stdout or "").splitlines()[:10]:
                lines.append(f"    {line}")
        elif plat == "Windows":
            stdout, stderr, rc = run_cmd(
                'wmic OS get FreePhysicalMemory,TotalVisibleMemorySize /value',
                shell=True,
            )
            lines.append(f"  wmic memory rc={rc}")
            if stdout:
                lines.append(f"    {stdout[:300]}")
        else:
            lines.append(f"  unsupported platform: {plat}")
        return lines

    def collect_disk():
        lines = []
        plat = platform.system()
        if plat in ("Linux", "Darwin"):
            stdout, stderr, rc = run_cmd(["df", "-h"])
            lines.append(f"  df -h rc={rc}")
            for line in (stdout or "").splitlines()[:12]:
                lines.append(f"    {line}")
            if stderr:
                lines.append(f"  df stderr: {stderr[:200]}")
        elif plat == "Windows":
            stdout, stderr, rc = run_cmd(
                'wmic logicaldisk get caption,freespace,size /value',
                shell=True,
            )
            lines.append(f"  wmic disk rc={rc}")
            if stdout:
                lines.append(f"    {stdout[:400]}")
        else:
            lines.append(f"  unsupported platform: {plat}")
        return lines

    def collect_network():
        lines = []
        plat = platform.system()
        if plat == "Linux":
            try:
                with open("/proc/net/dev", "r") as f:
                    content = f.read()
                for line in content.splitlines()[:6]:
                    lines.append(f"  {line}")
            except Exception as e:
                lines.append(f"  /proc/net/dev error: {e}")
            stdout, stderr, rc = run_cmd(["ss", "-s"])
            lines.append(f"  ss -s rc={rc}")
            for line in (stdout or "").splitlines()[:8]:
                lines.append(f"    {line}")
        elif plat == "Darwin":
            stdout, stderr, rc = run_cmd(["netstat", "-ib"])
            lines.append(f"  netstat -ib rc={rc}")
