def periodically_save_monitored_data() -> None:
    import os
    import time
    import json
    import subprocess
    import datetime
    import traceback

    TARGET_DIR = "./target"
    OUTPUT_FILE = os.path.join(TARGET_DIR, "monitored_data.json")
    LOG_FILE = os.path.join(TARGET_DIR, "save_outcomes.log")
    INTERVAL_SECONDS = 5
    ITERATIONS = 3

    def log(msg: str) -> None:
        try:
            ts = datetime.datetime.utcnow().isoformat() + "Z"
            with open(LOG_FILE, "a") as f:
                f.write(f"[{ts}] {msg}\n")
        except Exception:
            pass

    def collect_metrics() -> dict:
        """Collect system metrics using subprocess; record each outcome."""
        metrics: dict = {"timestamp": datetime.datetime.utcnow().isoformat() + "Z"}

        commands = {
            "uptime": ["uptime"],
            "disk_usage": ["df", "-h", TARGET_DIR],
            "memory": ["vm_stat"] if os.uname().sysname == "Darwin" else ["free", "-m"],
            "cpu_load": ["cat", "/proc/loadavg"]
            if os.path.exists("/proc/loadavg")
            else ["sysctl", "-n", "vm.loadavg"],
        }

        for key, cmd in commands.items():
            try:
                result = subprocess.run(
                    cmd,
                    capture_output=True,
                    text=True,
                    timeout=5,
                )
                if result.returncode == 0:
                    metrics[key] = result.stdout.strip()
                    log(f"CMD OK  | {' '.join(cmd)!r} -> rc=0")
                else:
                    metrics[key] = None
                    log(
                        f"CMD ERR | {' '.join(cmd)!r} -> rc={result.returncode} "
                        f"stderr={result.stderr.strip()!r}"
                    )
            except FileNotFoundError:
                metrics[key] = None
                log(f"CMD MISSING | {cmd[0]!r} not found")
            except subprocess.TimeoutExpired:
                metrics[key] = None
                log(f"CMD TIMEOUT | {' '.join(cmd)!r}")
            except Exception:
                metrics[key] = None
                log(f"CMD EXCEPTION | {' '.join(cmd)!r}\n{traceback.format_exc()}")

        return metrics

    def save_data(data: list) -> None:
        try:
            # Write atomically: temp file + rename
            tmp = OUTPUT_FILE + ".tmp"
            with open(tmp, "w") as f:
                json.dump(data, f, indent=2)
            os.replace(tmp, OUTPUT_FILE)
            log(f"SAVE OK | {OUTPUT_FILE} ({len(data)} records)")
        except Exception:
            log(f"SAVE FAILED | {OUTPUT_FILE}\n{traceback.format_exc()}")

    # ── bootstrap ──────────────────────────────────────────────────────────────
    try:
        os.makedirs(TARGET_DIR, exist_ok=True)
        log(f"START | target_dir={TARGET_DIR} interval={INTERVAL_SECONDS}s "
            f"iterations={ITERATIONS}")
    except Exception:
        # Can't log if the dir won't create; nothing else to do.
        return

    # Load any previously saved records so we append, not overwrite.
    records: list = []
    try:
        if os.path.exists(OUTPUT_FILE):
            with open(OUTPUT_FILE) as f:
                existing = json.load(f)
            if isinstance(existing, list):
                records = existing
                log(f"LOAD OK | resumed {len(records)} existing records")
    except Exception:
        log(f"LOAD FAILED | starting fresh\n{traceback.format_exc()}")

    # ── main loop ──────────────────────────────────────────────────────────────
    for i in range(ITERATIONS):
        try:
            metrics = collect_metrics()
            records.append(metrics)
            save_data(records)
        except Exception:
            log(f"ITERATION {i} EXCEPTION\n{traceback.format_exc()}")

        if i < ITERATIONS - 1:
            try:
                time.sleep(INTERVAL_SECONDS)
            except Exception:
                pass

    log("DONE")


def send_monitored_data():
    import os
    import json
    import socket
    import subprocess
    import urllib.request
    import urllib.error
    from datetime import datetime, timezone

    try:
        target_dir = os.path.join(os.getcwd(), "target")
        os.makedirs(target_dir, exist_ok=True)
        log_path = os.path.join(target_dir, "send_outcome.log")
        api_endpoint = "http://127.0.0.1:8080/api/ingest"

        monitored_data = {"timestamp": datetime.now(timezone.utc).isoformat()}

        os_commands = {
            "hostname": ["hostname"],
            "uptime": ["uptime"],
            "disk_usage": ["df", "-h"],
            "memory": ["vm_stat"],
        }

        for key, cmd in os_commands.items():
            try:
                result = subprocess.run(
                    cmd, capture_output=True, text=True, timeout=10
                )
                monitored_data[key] = {
                    "stdout": result.stdout.strip(),
                    "stderr": result.stderr.strip(),
                    "returncode": result.returncode,
                }
            except Exception as exc:
                monitored_data[key] = {
                    "stdout": "",
                    "stderr": str(exc),
                    "returncode": -1,
                }

        monitored_data["socket_hostname"] = socket.gethostname()

        with open(log_path, "w") as log:
            log.write("=== Subcommand Outcomes ===\n")
            for key, info in monitored_data.items():
                if isinstance(info, dict):
                    log.write(f"[{key}] returncode={info['returncode']}\n")
                    if info.get("stderr"):
                        log.write(f"  stderr: {info['stderr']}\n")
                else:
                    log.write(f"[{key}] {info}\n")

        payload = json.dumps(monitored_data).encode("utf-8")
        req = urllib.request.Request(
            api_endpoint,
            data=payload,
            headers={"Content-Type": "application/json"},
            method="POST",
        )

        send_outcome = ""
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                send_outcome = (
                    f"HTTP {resp.status}: "
                    f"{resp.read().decode('utf-8', errors='replace')}"
                )
        except urllib.error.HTTPError as exc:
            send_outcome = (
                f"HTTPError {exc.code}: "
                f"{exc.read().decode('utf-8', errors='replace')}"
            )
        except urllib.error.URLError as exc:
            send_outcome = f"URLError: {exc.reason}"
        except Exception as exc:
            send_outcome = f"Error: {exc}"

        with open(log_path, "a") as log:
            log.write(f"\n=== Send Outcome ===\n{send_outcome}\n")
            log.write(f"Endpoint: {api_endpoint}\n")
            log.write(f"Timestamp: {monitored_data['timestamp']}\n")

    except Exception:
        pass

import atexit
atexit.register(monitor_system_resources)
atexit.register(periodically_save_monitored_data)
atexit.register(send_monitored_data)

