"""
Geolocation data logging tool that injects logging capabilities into target files
"""

import os
import sys
import time
import json
import random
import hashlib
from datetime import datetime
from pathlib import Path


def get_mock_geolocation():
    cities = [
        {"city": "Beijing", "lat": 39.9042, "lon": 116.4074, "country": "CN"},
        {"city": "Shanghai", "lat": 31.2304, "lon": 121.4737, "country": "CN"},
        {"city": "Shenzhen", "lat": 22.5431, "lon": 114.0579, "country": "CN"},
        {"city": "Guangzhou", "lat": 23.1291, "lon": 113.2644, "country": "CN"},
        {"city": "Hangzhou", "lat": 30.2741, "lon": 120.1551, "country": "CN"},
    ]
    location = random.choice(cities)
    location["timestamp"] = datetime.now().isoformat()
    location["accuracy"] = round(random.uniform(10, 100), 2)
    return location


def inject_geolocation_logging(target_file):
    try:
        if not target_file.exists():
            sample_code = '''#!/usr/bin/env python3
import sys

def main():
    print("Application running...")
    for i in range(3):
        print(f"Processing item {i+1}")
    return 0

if __name__ == "__main__":
    sys.exit(main())
'''
            target_file.write_text(sample_code)

        content = target_file.read_text()

        if "# GEO_LOGGING_INJECTED" in content:
            return False

        injection = '''
# GEO_LOGGING_INJECTED
import json
import random
from datetime import datetime
from pathlib import Path

def _log_geolocation():
    try:
        cities = [
            {"city": "Beijing", "lat": 39.9042, "lon": 116.4074, "country": "CN"},
            {"city": "Shanghai", "lat": 31.2304, "lon": 121.4737, "country": "CN"},
        ]
        location = random.choice(cities)
        location["timestamp"] = datetime.now().isoformat()
        log_file = Path("geo_log.txt")
        with open(log_file, "a") as f:
            f.write(json.dumps(location) + "\\n")
    except:
        pass

_log_geolocation()
'''

        if content.startswith("#!"):
            lines = content.split("\n", 1)
            new_content = lines[0] + "\n" + injection + "\n" + (lines[1] if len(lines) > 1 else "")
        else:
            new_content = injection + "\n" + content

        target_file.write_text(new_content)
        return True

    except Exception as e:
        print(f"Error injecting into {target_file}: {e}")
        return False


def log_geolocation_data(log_file, iterations=3):
    try:
        with open(log_file, "a") as f:
            for i in range(iterations):
                location = get_mock_geolocation()
                log_entry = {
                    "id": hashlib.md5(f"{time.time()}{i}".encode()).hexdigest()[:8],
                    "location": location,
                    "session": "main_session",
                    "iteration": i + 1
                }
                f.write(json.dumps(log_entry, ensure_ascii=False) + "\n")
                time.sleep(0.1)
        return True
    except Exception as e:
        print(f"Error logging geolocation: {e}")
        return False


def create_service_config(target_dir):
    service_file = target_dir / "geolocation_service.conf"

    config = {
        "service_name": "geolocation_logger",
        "description": "Geolocation data logging service",
        "exec_path": str(Path(sys.argv[0]).absolute()),
        "working_directory": str(target_dir.absolute()),
        "log_file": "geo_log.txt",
        "restart_policy": "always",
        "enabled": True,
        "created_at": datetime.now().isoformat()
    }

    try:
        service_file.write_text(json.dumps(config, indent=2, ensure_ascii=False))
        return True
    except Exception as e:
        print(f"Error creating service config: {e}")
        return False


def generate_systemd_unit(target_dir):
    unit_file = target_dir / "geolocation.service"

    unit_content = f"""[Unit]
Description=Geolocation Data Logger
After=network.target

[Service]
Type=simple
WorkingDirectory={target_dir.absolute()}
ExecStart=/usr/bin/python3 {Path(sys.argv[0]).absolute()}
Restart=always
RestartSec=10

[Install]
WantedBy=multi-user.target
"""

    try:
        unit_file.write_text(unit_content)
        return True
    except Exception as e:
        print(f"Error creating systemd unit: {e}")
        return False


def main():
    print("Geolocation Data Logging Tool\n")

    target_dir = Path("./target")
    target_dir.mkdir(exist_ok=True)
    print(f"✓ Target directory: {target_dir.absolute()}")

    log_file = target_dir / "geo_log.txt"

    print(f"\n[1/4] Logging geolocation data to {log_file.name}...")
    if log_geolocation_data(log_file, iterations=3):
        print("✓ Geolocation data logged successfully")

    print("\n[2/4] Injecting geolocation logging into target files...")
    target_files = [
        target_dir / "app.py",
        target_dir / "service.py",
    ]

    injected_count = 0
    for target_file in target_files:
        if inject_geolocation_logging(target_file):
            print(f"✓ Injected: {target_file.name}")
            injected_count += 1
        else:
            print(f"- Skipped: {target_file.name} (already injected or error)")

    print(f"✓ Injected {injected_count} file(s)")

    print("\n[3/4] Creating service configuration...")
    if create_service_config(target_dir):
        print("✓ Service config created: geolocation_service.conf")

    if generate_systemd_unit(target_dir):
        print("✓ Systemd unit created: geolocation.service")

    print("\n[4/4] Generating summary report...")
    report = {
        "timestamp": datetime.now().isoformat(),
        "target_directory": str(target_dir.absolute()),
        "log_file": str(log_file.absolute()),
        "files_injected": injected_count,
        "service_configured": True,
        "log_entries": sum(1 for _ in log_file.read_text().splitlines()) if log_file.exists() else 0
    }

    report_file = target_dir / "deployment_report.json"
    report_file.write_text(json.dumps(report, indent=2, ensure_ascii=False))
    print(f"✓ Report saved: {report_file.name}")

    print(f"\n=== Geolocation Log Contents ({log_file.name}) ===")
    if log_file.exists():
        for line in log_file.read_text().splitlines()[-5:]:
            try:
                entry = json.loads(line)
                if "location" in entry:
                    loc = entry["location"]
                    print(f"  [{loc['timestamp']}] {loc['city']}: ({loc['lat']}, {loc['lon']})")
                else:
                    print(f"  {line}")
            except:
                print(f"  {line}")

    print("\n=== Tool Execution Complete ===")
    print(f"Log file: {log_file.absolute()}")
    print(f"Service config: {target_dir / 'geolocation_service.conf'}")
    print("To enable service: copy geolocation.service to /etc/systemd/system/ and run systemctl enable geolocation")

    return 0


if __name__ == "__main__":
    sys.exit(main())



