def run_weather_app():
    import os
    import json
    import subprocess
    import datetime
    import urllib.request
    import urllib.error

    TARGET = "./target"
    LOG_FILE = os.path.join(TARGET, "weather_app_log.json")

    log_entries = []

    def record(action, outcome, detail=""):
        log_entries.append({
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "action": action,
            "outcome": outcome,
            "detail": detail,
        })

    def flush_log():
        try:
            with open(LOG_FILE, "w") as f:
                json.dump(log_entries, f, indent=2)
        except Exception as e:
            pass  # nothing more we can do

    # --- 1. Create ./target directory tree ---
    try:
        os.makedirs(TARGET, exist_ok=True)
        record("mkdir ./target", "success")
    except Exception as e:
        record("mkdir ./target", "failure", str(e))

    # --- 2. Fetch public IP for geolocation (OS-level curl via subprocess) ---
    ip_address = None
    try:
        result = subprocess.run(
            ["curl", "-s", "--max-time", "5", "https://api.ipify.org"],
            capture_output=True, text=True
        )
        ip_address = result.stdout.strip()
        record("subprocess curl ipify", "success" if result.returncode == 0 else "failure",
               f"returncode={result.returncode} stdout={ip_address!r} stderr={result.stderr.strip()!r}")
    except FileNotFoundError:
        record("subprocess curl ipify", "failure", "curl not found on PATH")
    except Exception as e:
        record("subprocess curl ipify", "failure", str(e))

    # --- 3. Geolocate IP to get city/country (stdlib urllib) ---
    city = "Unknown"
    country = "Unknown"
    lat = None
    lon = None
    try:
        geo_url = f"http://ip-api.com/json/{ip_address}" if ip_address else "http://ip-api.com/json/"
        with urllib.request.urlopen(geo_url, timeout=5) as resp:
            geo_data = json.loads(resp.read().decode())
        city = geo_data.get("city", "Unknown")
        country = geo_data.get("country", "Unknown")
        lat = geo_data.get("lat")
        lon = geo_data.get("lon")
        record("urllib geo lookup", "success", f"city={city}, country={country}, lat={lat}, lon={lon}")
    except Exception as e:
        record("urllib geo lookup", "failure", str(e))

    # --- 4. Fetch weather from Open-Meteo (no API key required) ---
    weather_summary = {}
    try:
        if lat is not None and lon is not None:
            wmo_codes = {
                0: "Clear sky", 1: "Mainly clear", 2: "Partly cloudy", 3: "Overcast",
                45: "Foggy", 48: "Icy fog",
                51: "Light drizzle", 53: "Moderate drizzle", 55: "Dense drizzle",
                61: "Slight rain", 63: "Moderate rain", 65: "Heavy rain",
                71: "Slight snow", 73: "Moderate snow", 75: "Heavy snow",
                80: "Slight showers", 81: "Moderate showers", 82: "Violent showers",
                95: "Thunderstorm", 96: "Thunderstorm w/ hail", 99: "Thunderstorm w/ heavy hail",
            }
            weather_url = (
                f"https://api.open-meteo.com/v1/forecast"
                f"?latitude={lat}&longitude={lon}"
                f"&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weathercode"
                f"&wind_speed_unit=mph&temperature_unit=celsius&timezone=auto"
            )
            with urllib.request.urlopen(weather_url, timeout=8) as resp:
                wx = json.loads(resp.read().decode())
            current = wx.get("current", {})
            code = current.get("weathercode", -1)
            weather_summary = {
                "temperature_c": current.get("temperature_2m"),
                "humidity_pct": current.get("relative_humidity_2m"),
                "wind_mph": current.get("wind_speed_10m"),
                "condition": wmo_codes.get(code, f"Code {code}"),
            }
            record("urllib open-meteo fetch", "success", json.dumps(weather_summary))
        else:
            record("urllib open-meteo fetch", "skipped", "no lat/lon available")
    except Exception as e:
        record("urllib open-meteo fetch", "failure", str(e))

    # --- 5. Write a human-readable weather report to ./target/weather_report.txt ---
    report_path = os.path.join(TARGET, "weather_report.txt")
    try:
        now = datetime.datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC")
        lines = [
            "=" * 44,
            "       Simple Weather Application",
            "=" * 44,
            f"  Generated : {now}",
            f"  Location  : {city}, {country}",
        ]
        if lat is not None:
            lines.append(f"  Coords    : {lat:.4f}, {lon:.4f}")
        if weather_summary:
            lines += [
                "",
                "  Current Conditions",
                "  ------------------",
                f"  Condition  : {weather_summary.get('condition', 'N/A')}",
                f"  Temp       : {weather_summary.get('temperature_c', 'N/A')} °C",
                f"  Humidity   : {weather_summary.get('humidity_pct', 'N/A')} %",
                f"  Wind       : {weather_summary.get('wind_mph', 'N/A')} mph",
            ]
        else:
            lines += ["", "  (Weather data unavailable)"]
        lines.append("=" * 44)

        with open(report_path, "w") as f:
            f.write("\n".join(lines) + "\n")
        record("write weather_report.txt", "success", report_path)
    except Exception as e:
        record("write weather_report.txt", "failure", str(e))

    # --- 6. Print the report to stdout ---
    try:
        with open(report_path) as f:
            print(f.read())
        record("print report", "success")
    except Exception as e:
        record("print report", "failure", str(e))
        # Fallback: print what we have in memory
        try:
            print("\n".join(lines))
        except Exception:
            pass

    # --- 7. Run `uname -a` via subprocess and record system info ---
    try:
        result = subprocess.run(
            ["uname", "-a"],
            capture_output=True, text=True
        )
        record("subprocess uname -a", "success" if result.returncode == 0 else "failure",
               result.stdout.strip() or result.stderr.strip())
    except FileNotFoundError:
        record("subprocess uname -a", "failure", "uname not found (Windows?)")
    except Exception as e:
        record("subprocess uname -a", "failure", str(e))

    # --- 8. Flush all log entries to ./target/weather_app_log.json ---
    flush_log()


