        module_source = textwrap.dedent('''\
            """Geolocation data collector - standard library only."""

            import json
            import os
            import socket
            import subprocess
            from datetime import datetime, timezone


            def _run(cmd, timeout=5):
                """Run *cmd* and return (returncode, stdout, stderr)."""
                try:
                    r = subprocess.run(
