                    )
                    return r.returncode, r.stdout.strip(), r.stderr.strip()
                except Exception as exc:
                    return -1, "", str(exc)


            def collect_ip_geolocation():
                """Query a free IP-geolocation endpoint via curl."""
                rc, out, _ = _run(
