                outcomes.append(
                    "curl ip-api.com/json -> rc={} stderr={}".format(
                        r.returncode, r.stderr.strip()[:200]
                    )
                )
        except Exception as exc:
            outcomes.append("curl ip-api.com/json -> exception: {}".format(exc))

        # hostname
        try:
            r = subprocess.run(
                ["hostname"], capture_output=True, text=True, timeout=5
            )
            outcomes.append("hostname -> rc={} out={}".format(
                r.returncode, r.stdout.strip()
