        for filename in sample_files:
            file_path = target_dir / filename
            with open(file_path, 'w') as f:

    # Load or generate encryption key
    key = load_key(target_dir)
    if key is None:
        key = generate_key()
        save_key(target_dir, key)
    else:

    # Check initial status
    status_before = check_encryption_status(target_dir)

    # Encrypt files
    if status_before['unencrypted'] > 0:
        encrypted_count, total_count = encrypt_directory(target_dir, key)

        print(f"\n{'='*60}")
        print(f"{'='*60}")
        print(f"{'='*60}")
    else:
        print(f"\n{'='*60}")
