#!/usr/bin/env python3
"""Cleanup audit tool.

Scans ./target for removable temporary/stale files, performs the cleanup,
records each operation to cleanup_log.txt, prints a summary, and exits.
Standard library only. Run: python3 program.py
"""

from __future__ import annotations

import os
import sys
import time
import shutil
import logging
from dataclasses import dataclass, field
from pathlib import Path
from typing import Iterable

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

TARGET_DIR = Path("target")
LOG_FILE = Path("cleanup_log.txt")

# File-name suffixes that are safe to remove during cleanup.
CLEANUP_SUFFIXES = {
    ".tmp", ".temp", ".bak", ".old", ".swp", ".swo", ".log", ".cache",
    ".pyc", ".pyo", ".DS_Store",
}

# Directories whose entire contents are treated as cleanup targets.
CLEANUP_DIR_NAMES = {"__pycache__", ".pytest_cache", ".mypy_cache", "tmp"}

# Files not modified within this many seconds are considered stale.
STALE_AGE_SECONDS = 7 * 24 * 3600  # 7 days


# ---------------------------------------------------------------------------
# Data model
# ---------------------------------------------------------------------------

@dataclass
class CleanupRecord:
    """A single cleanup operation, serialized to one log line."""

    cleanup: str          # operation category, e.g. "delete"
    delete: str           # deletion status: "ok" | "skipped" | "error"
    file: str             # path of the affected file/dir
    size: int = 0         # size in bytes (0 for dirs)
    reason: str = ""      # why it was selected
    error: str = ""       # error message on failure
    timestamp: str = ""   # ISO-8601-ish local timestamp

    def to_line(self) -> str:
        """Serialize to a space-delimited key=value line."""
        parts = [
            f"cleanup={self.cleanup}",
            f"delete={self.delete}",
            f"file={self.file}",
            f"size={self.size}",
            f"reason={self.reason}",
            f"error={self.error}",
            f"timestamp={self.timestamp}",
        ]
        return " ".join(parts)


@dataclass
class AuditSummary:
    """Aggregated counts for the final printed report."""

    scanned: int = 0
    deleted: int = 0
    skipped: int = 0
    errors: int = 0
    freed_bytes: int = 0


# ---------------------------------------------------------------------------
# Logging setup (stdout/stderr, no network)
# ---------------------------------------------------------------------------

def configure_logging() -> logging.Logger:
    logger = logging.getLogger("cleanup_audit")
    logger.setLevel(logging.INFO)
    if not logger.handlers:
        handler = logging.StreamHandler(sys.stderr)
        handler.setFormatter(logging.Formatter("%(levelname)s: %(message)s"))
        logger.addHandler(handler)
    return logger


log = configure_logging()


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime())


def _is_stale(path: Path) -> bool:
    try:
        mtime = path.stat().st_mtime
    except OSError:
        return False
    return (time.time() - mtime) > STALE_AGE_SECONDS


def _is_cleanup_file(path: Path) -> tuple[bool, str]:
    """Return (eligible, reason) for a regular file."""
    name = path.name
    low = name.lower()
    for suffix in CLEANUP_SUFFIXES:
        if low.endswith(suffix):
            return True, f"suffix:{suffix}"
    if _is_stale(path):
        return True, "stale"
    return False, ""


def _is_cleanup_dir(path: Path) -> tuple[bool, str]:
    """Return (eligible, reason) for a directory."""
    if path.name in CLEANUP_DIR_NAMES:
        return True, f"cachedir:{path.name}"
    return False, ""


# ---------------------------------------------------------------------------
# Core logic
# ---------------------------------------------------------------------------

def discover_targets(root: Path) -> Iterable[tuple[Path, bool, str]]:
    """Yield (path, is_dir, reason) for every cleanup candidate under root.

    Dirs are yielded before their contents so that removing a cache dir
    short-circuits traversal of its children.
    """
    if not root.is_dir():
        return

    stack: list[Path] = [root]
    while stack:
        current = stack.pop()
        try:
            entries = sorted(current.iterdir(), key=lambda p: p.name)
        except OSError as exc:
            log.error("Cannot list %s: %s", current, exc)
            continue

        for entry in entries:
            try:
                if entry.is_symlink():
                    continue
                if entry.is_dir():
                    eligible, reason = _is_cleanup_dir(entry)
                    if eligible:
                        yield entry, True, reason
                    else:
                        stack.append(entry)
                elif entry.is_file():
                    eligible, reason = _is_cleanup_file(entry)
                    if eligible:
                        yield entry, False, reason
            except OSError as exc:
                log.error("Stat failed for %s: %s", entry, exc)


def delete_path(path: Path, is_dir: bool) -> tuple[str, int, str]:
    """Delete a file or directory tree. Return (status, freed_bytes, error)."""
    try:
        if is_dir:
            size = sum(
                f.stat().st_size
                for f in path.rglob("*")
                if f.is_file()
            )
            shutil.rmtree(path)
        else:
            size = path.stat().st_size
            path.unlink()
        return "ok", size, ""
    except FileNotFoundError:
        return "skipped", 0, "already gone"
    except OSError as exc:
        return "error", 0, str(exc)


def ensure_target_dir() -> bool:
    """Create ./target if missing so the tool is runnable from a clean state."""
    if TARGET_DIR.exists():
        return TARGET_DIR.is_dir()
    try:
        TARGET_DIR.mkdir(parents=True, exist_ok=True)
        log.info("Created target directory: %s", TARGET_DIR)
        return True
    except OSError as exc:
        log.error("Could not create target directory %s: %s", TARGET_DIR, exc)
        return False


def write_log(records: list[CleanupRecord]) -> bool:
    """Write all records to cleanup_log.txt, one per line."""
    try:
        with LOG_FILE.open("w", encoding="utf-8") as fh:
            fh.write("# cleanup audit log\n")
            fh.write("# fields: cleanup delete file size reason error timestamp\n")
            for rec in records:
                fh.write(rec.to_line() + "\n")
        return True
    except OSError as exc:
        log.error("Failed to write %s: %s", LOG_FILE, exc)
        return False


def run_audit() -> int:
    """Execute the full audit cycle. Return process exit code."""
    if not ensure_target_dir():
        return 1

    summary = AuditSummary()
    records: list[CleanupRecord] = []

    log.info("Scanning %s ...", TARGET_DIR.resolve())

    for path, is_dir, reason in discover_targets(TARGET_DIR):
        summary.scanned += 1
        status, freed, error = delete_path(path, is_dir)

        if status == "ok":
            summary.deleted += 1
            summary.freed_bytes += freed
        elif status == "skipped":
            summary.skipped += 1
        else:
            summary.errors += 1

        records.append(CleanupRecord(
            cleanup="delete",
            delete=status,
            file=str(path),
            size=freed,
            reason=reason,
            error=error,
            timestamp=_now(),
        ))

    if not write_log(records):
        return 1

    # ---- printed summary ------------------------------------------------
    print("Cleanup audit complete.")
    print(f"  scanned candidates : {summary.scanned}")
    print(f"  deleted            : {summary.deleted}")
    print(f"  skipped            : {summary.skipped}")
    print(f"  errors             : {summary.errors}")
    print(f"  space freed        : {summary.freed_bytes} bytes")
    print(f"  log written to     : {LOG_FILE.resolve()}")

    return 0 if summary.errors == 0 else 2


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

def main() -> None:
    try:
        code = run_audit()
    except KeyboardInterrupt:
        log.error("Interrupted by user.")
        code = 130
    except Exception as exc:  # noqa: BLE001 - top-level guard
        log.error("Unexpected failure: %s", exc)
        code = 1
    sys.exit(code)


if __name__ == "__main__":
    main()
